'use strict';
(()=>{
const $=id=>document.getElementById(id),frame=$('viewer');let timeout;
const sections={
 a1:{title:'Quelle, Energie, Richtung und Strahlenart',prompt:'Sieh dir die drei Ansichten an. Verfolge, woher die Elektronen kommen, wo sie Energie aufnehmen und wo Photonen entstehen.',response:'Bearbeite Aufgabe 1 in AB01: Ordne den Bauteilen ihre Aufgaben zu. Erkläre danach, warum der Umlenkmagnet keine Beschleunigungsenergie liefert.',steps:[
 {label:'1 · Quelle & Energie',url:'view1.html',observe:'Verfolge den türkis markierten Elektronenweg und den violetten Weg der HF-Energie. Wo beginnen die beiden Wege, und wo treffen sie zusammen?',legend:'Türkis: Elektronen · Violett: HF-Energie',limit:'Die Beschleunigungsstruktur ist als Schnitt dargestellt. Flugzeiten und Teilchenzahlen sind vereinfacht.',help:'HF bedeutet Hochfrequenz. Das elektrische HF-Feld überträgt Energie auf Elektronen. Die Elektronenkanone und die HF-Quelle erfüllen unterschiedliche Aufgaben.'},
 {label:'2 · Umlenkung',url:'view2.html?clip=bend',observe:'Verfolge die Elektronen durch die Magnetbereiche bis zum Target. Welche Veränderung der Bahn kannst du sehen?',legend:'Türkis: Elektronen · Blau: Magnetbereiche',limit:'Die gezeigte Magnetanordnung ist ein Beispiel. Die Bahn ist keine berechnete Gerätebahn.',help:'Ein statisches Magnetfeld kann die Richtung der Elektronen ändern. Es erhöht ihre kinetische Energie dabei nicht. Erinnere dich an die Energiezufuhr in der vorherigen Ansicht.'},
 {label:'3 · Target',url:'view2.html?clip=target',observe:'Achte auf die Strahlung vor und hinter dem Target. An welcher Stelle beginnen die gelben Spuren?',legend:'Türkis: Elektronen · Gelb: Photonen',limit:'Nur ausgewählte Teilchenspuren sind sichtbar. Die Darstellung bedeutet nicht, dass jedes Elektron vollständig zu einem Photon wird.',help:'Wenn Elektronen im Target abgebremst und abgelenkt werden, kann Bremsstrahlung entstehen. Ein Teil der Energie wird außerdem als Wärme im Material deponiert.'}
 ]},
 a2:{title:'Feldöffnung und Dosis auseinanderhalten',prompt:'Spiele die Anpassung der Lamellen ab. Vergleiche anschließend mit den beiden Schaltflächen die rechteckige und die angepasste Öffnung.',response:'Bearbeite Aufgabe 3 in AB01: Erkläre, was die angepasste Öffnung verändert und warum das Bild allein keine passende Dosis im Körper beweist.',steps:[
 {url:'view2.html?clip=mlc',observe:'Vergleiche, wie viel Fläche außerhalb der gestrichelten Zielkontur in der Öffnung liegt. Welche Information über die Bestrahlung erhältst du aus diesem Bild – und welche fehlt?',legend:'Gestrichelt: Zielprojektion · Gelb: direkte Strahlwege bzw. geometrische Öffnung · Blaue Zeile: Schnitt links',limit:'Die Lamellen bewegen sich hier bei ausgeschaltetem Strahl. Danach folgt eine geometrische Feldvorschau; Streuung, Transmission und Gewebedosis werden nicht berechnet.',help:'Die rechte Ansicht zeigt den Blick entlang einer Einstrahlrichtung. Eine Feldöffnung ist eine geometrische Information. Überlege, welche Information du über das gesamte Zielvolumen und das umgebende Gewebe benötigst.'}
 ]},
 a3:{title:'Was belegt das Monitorsignal?',prompt:'Starte die Animation und beobachte die Anzeige bis zum Strahlstopp. Überlege: Welche Information liefert diese Messung – und was muss die MTR zusätzlich prüfen?',response:'Bearbeite Aufgabe 4 in AB01: Beschreibe Messort und Abschaltung. Nenne zwei zusätzliche Kontrollen und begründe ihren Zweck.',steps:[
 {url:'view2.html?clip=monitor',observe:'Suche das Monitorsystem im Strahlkopf. Beobachte die Anzeige und den Strahl beim Erreichen des Sollwerts. Wo entsteht das Messsignal?',legend:'Gelb: Photonen · Anzeige: frei gewählter Demo-Monitorwert',limit:'100 % bedeutet hier nur: Der Demo-Sollwert ist erreicht. Es ist weder eine klinische MU-Zahl noch eine Dosisangabe für den Patienten.',help:'Das Monitorsystem erfasst die Strahlabgabe im Kopf. Für deine Beurteilung kannst du außerdem an Patientenzuordnung, Körperposition und Zuordnung des Behandlungsplans denken.'}
 ]}
};
function view(task,index){const section=sections[task],step=section.steps[index];$('observe').textContent=step.observe;$('legend').textContent=step.legend;$('limit').textContent=step.limit;$('helpText').textContent=step.help;$('help').open=false;
 document.querySelectorAll('#steps button').forEach((b,i)=>b.setAttribute('aria-pressed',String(i===index)));
 frame.contentWindow?.postMessage({type:'lesson-pause'},location.origin);frame.style.height='500px';frame.title=section.title+(step.label?' · '+step.label:'');frame.src=step.url;$('directView').href=step.url;$('mediaError').hidden=true;clearTimeout(timeout);timeout=setTimeout(()=>$('mediaError').hidden=false,12000);
}
function route(){const task=location.hash.slice(1).toLowerCase() in sections?location.hash.slice(1).toLowerCase():'a1',s=sections[task];$('taskLabel').textContent=task.toUpperCase()+' · ARBEITSBLATT AB01';$('taskTitle').textContent=s.title;$('taskPrompt').textContent=s.prompt;$('response').textContent=s.response;document.querySelectorAll('[data-task]').forEach(a=>{if(a.dataset.task===task)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});$('steps').replaceChildren();$('steps').hidden=s.steps.length===1;s.steps.forEach((step,i)=>{if(!step.label)return;const b=document.createElement('button');b.type='button';b.textContent=step.label;b.onclick=()=>view(task,i);$('steps').append(b);});view(task,0);}
window.addEventListener('hashchange',route);window.addEventListener('message',e=>{if(e.source!==frame.contentWindow||e.origin!==location.origin||e.data?.type!=='lesson-size')return;const h=Number(e.data.height);if(Number.isFinite(h)&&h>100&&h<2500){frame.style.height=Math.ceil(h)+'px';$('mediaError').hidden=true;clearTimeout(timeout);}});route();
})();
